#!/usr/bin/env python3
"""Deterministic support enumeration; exact singleton-unit certificates, no floats."""
import argparse
import gzip
import hashlib
import itertools
import json
import math
import os
from pathlib import Path
import sys
import time


def supports(degree, max_terms):
    for size in range(2, min(degree + 1, max_terms) + 1):
        for interior in itertools.combinations(range(1, degree), size - 2):
            yield (0, *interior, degree)


def canonical(I, J):
    if (len(I), I) > (len(J), J) and I[-1] == J[-1]:
        return False
    if math.gcd(*I, *J) != 1:
        return False
    pair = (I, J)
    rev = (tuple(I[-1] - i for i in reversed(I)),
           tuple(J[-1] - j for j in reversed(J)))
    if I[-1] == J[-1] and (len(rev[0]), rev[0]) > (len(rev[1]), rev[1]):
        rev = (rev[1], rev[0])
    # Compare using the same total ordering used for swapping.
    key = lambda p: ((len(p[0]), p[0]), (len(p[1]), p[1]))
    return key(pair) <= key(rev)


def classify(I, J):
    diagonals = {}
    for i in I:
        for j in J:
            diagonals.setdefault(i + j, []).append((i, j))
    unitI, unitJ = {0, I[-1]}, {0, J[-1]}
    for edges in diagonals.values():
        if len(edges) == 1:
            i, j = edges[0]
            unitI.add(i)
            unitJ.add(j)
    collisions = False
    for k in sorted(diagonals):
        edges = diagonals[k]
        if len(edges) > 1:
            collisions = True
            for i, j in edges:
                if i in unitI and j in unitJ:
                    return "excluded", [k, i, j]
    return ("unknown" if collisions else "fair"), None


"""Injected after frozen classifier: only fresh total-degree 49/50 jobs."""
import base64,io,multiprocessing,platform
def compute50(job):
 total,m,n,index,I=job["total"],job["m"],job["n"],job["index"],tuple(job["I"])
 assert total in (49,50) and m+n==total and 1<=m<=total//2 and index>=0 and I[0]==0 and I[-1]==m
 counts=dict(raw=0,canonical=0,excluded=0,fair=0,unknown=0);buf=io.BytesIO();dig=hashlib.sha256();unknown=[]
 with gzip.GzipFile(fileobj=buf,mode="wb",compresslevel=1,mtime=0) as z:
  for J in supports(n,6):
   counts["raw"]+=1
   if not canonical(I,J):continue
   status,witness=classify(I,J);line=(json.dumps([I,J,status,witness],separators=(",",":"))+"\n").encode();z.write(line);dig.update(line);counts["canonical"]+=1;counts[status]+=1
   if status=="unknown":unknown.append([I,J])
 packed=buf.getvalue();return {"event":"chunk","total":total,"m":m,"n":n,"index":index,"I":I,"counts":counts,"unknown":unknown,"raw_sha256":dig.hexdigest(),"gzip_sha256":hashlib.sha256(packed).hexdigest(),"gzip_base64":base64.b64encode(packed).decode()}
def emit50(x):print(json.dumps(x,separators=(",",":")),flush=True)
def run_support50(jobs,plan_sha256,source_sha256,workers=15,seconds=14400):
 assert workers==15 and seconds==14400;permitted={(x["total"],x["m"],x["n"],x["index"],tuple(x["I"])) for x in jobs};assert len(permitted)==len(jobs)
 begin=time.monotonic();pending=[];cursor=finished=0;timed=False
 emit50({"event":"support50_remote_started","pid":os.getpid(),"worker_pids":[],"workers":workers,"python":sys.version,"host":platform.node(),"frozen_source_sha256":source_sha256,"plan_sha256":plan_sha256,"selected_jobs":len(jobs),"total_min":49,"total_max":50,"cap":6,"seconds_limit":seconds,"storage":"worker RAM only; completed chunks stream to local data ledger"})
 with multiprocessing.get_context("fork").Pool(workers) as pool:
  emit50({"event":"support50_remote_workers","worker_pids":[p.pid for p in pool._pool]})
  while True:
   while cursor<len(jobs) and len(pending)<2*workers and time.monotonic()-begin<seconds:pending.append(pool.apply_async(compute50,(jobs[cursor],)));cursor+=1
   if cursor<len(jobs) and time.monotonic()-begin>=seconds:timed=True
   ready=[x for x in pending if x.ready()]
   for item in ready:emit50(item.get());pending.remove(item);finished+=1
   if not pending and (cursor==len(jobs) or timed):break
   if not ready:time.sleep(.01)
  pool.close();pool.join()
 event="support50_selected_complete" if cursor==len(jobs) and not timed else "support50_selected_partial_timeout"
 emit50({"event":event,"workers_joined":True,"submitted":cursor,"finished":finished,"selected_jobs":len(jobs),"complete_selected_set":event=="support50_selected_complete","seconds":time.monotonic()-begin,"scope":"Fresh total-degree 49/50 plan only; no prior batch coverage or general conclusion."})

